/**
 * Pagdandi Books & Café — the showcase's independent bookshop with a café
 * corner, at 14 Prabhat Road, Lane 3, Deccan Gymkhana, Pune 411004. Anagha
 * Joshi runs the shop; Siddharth Kale runs the café corner.
 *
 * Books are public-domain classics or clearly fictional titles by fictional
 * Pune writers; every imprint and maker is invented. Book covers are drawn
 * for this seed (`pagdandi-covers.ts`, generated by
 * `scripts/demo-covers/generate-pagdandi-covers.mjs`, whose book list must
 * match this one). Stationery and café photographs are free-licence Unsplash
 * images, each credited to its photographer and looked at before use.
 *
 * Data only; `demo-shop.ts` writes it.
 */

import type {
    DemoCategory,
    DemoOption,
    DemoPhoto,
    DemoProduct,
    DemoReview,
    DemoVariant,
} from "./demo-shop-types";
import { PAGDANDI_COVERS } from "./pagdandi-covers";

// ---------------------------------------------------------------- helpers

function drawn(key: string, alt: string): DemoPhoto {
    const url = PAGDANDI_COVERS[key];
    if (!url) throw new Error(`pagdandi-covers has no image "${key}"`);
    return {
        url,
        alt,
        width: 600,
        height: 900,
        creditName: null,
        creditUrl: null,
    };
}

function unsplash(
    id: string,
    alt: string,
    width: number,
    height: number,
    creditName: string,
    username: string,
): DemoPhoto {
    return {
        url: `https://images.unsplash.com/photo-${id}?w=1600&q=80&auto=format&fit=crop`,
        alt,
        width,
        height,
        creditName,
        creditUrl: `https://unsplash.com/@${username}`,
    };
}

function rv(
    rating: DemoReview["rating"],
    displayName: string,
    body: string,
    variantTitle: string | null = null,
    reply: string | null = null,
): DemoReview {
    return { rating, body, displayName, variantTitle, reply };
}

function v(
    title: string,
    sku: string,
    price: string,
    stock: number,
    image: number | null = null,
    mrp: string | null = null,
): DemoVariant {
    return { title, sku, price, mrp, stock, image };
}

function cheapest(variants: DemoVariant[]): string {
    return variants
        .map((x) => x.price)
        .reduce((a, b) => (Number(b) < Number(a) ? b : a));
}

