type Edition = [title: string, price: string, stock: number, mrp?: string];

interface BookInput {
    slug: string;
    name: string;
    author: string;
    category: string;
    language: string;
    pages: number;
    /** Editions; leave out for a single-edition book and give price and stock. */
    editions?: Edition[];
    price?: string;
    stock?: number;
    mrp?: string;
    description: string;
    points?: string[];
    materials?: string;
    howToUse?: string;
    maker: { name: string; madeIn: string };
    demand: number;
    status?: DemoProduct["status"];
    seasonal?: DemoProduct["seasonal"];
    lowStockAlert?: number;
    returnsText?: string;
    tracked?: boolean;
    reviews?: DemoReview[];
}

function skuBase(slug: string): string {
    const words = slug.split("-");
    return words.length <= 2
        ? words.join("").toUpperCase().slice(0, 10)
        : words
              .map((w) => w[0])
              .join("")
              .toUpperCase();
}

function book(b: BookInput): DemoProduct {
    const base = `PGD-${skuBase(b.slug)}`;
    const variants = (b.editions ?? []).map(([title, price, stock, mrp]) =>
        v(
            title,
            `${base}-${EDITION_CODE[title]}`,
            price,
            stock,
            null,
            mrp ?? null,
        ),
    );
    const titles = variants.map((x) => x.title);
    const hasHard = titles.some((t) => t.endsWith(HB));
    const hasUsed = titles.includes(USED);
    const materials =
        b.materials ??
        [
            "Paperback on 70 gsm natural-shade paper, section-sewn and glued, matt laminated cover.",
            hasHard
                ? "Hardcover: cloth-bound boards, sewn, with a ribbon marker."
                : null,
            hasUsed
                ? "Used copies: the edition we have in at the time; condition noted on the slip."
                : null,
        ]
            .filter(Boolean)
            .join(" ");
    const points = [
        `Pages: ${b.pages}`,
        `Language: ${b.language}`,
        ...(b.points ?? []),
        ...(hasUsed
            ? [
                  "Used copies are checked page by page; any marks are noted on the slip",
              ]
            : []),
    ];
    return {
        slug: b.slug,
        name: b.name,
        category: b.category,
        option: variants.length ? "edition" : null,
        price: variants.length ? cheapest(variants) : (b.price ?? "0"),
        mrp: variants.length ? null : (b.mrp ?? null),
        status: b.status ?? "PUBLISHED",
        description: b.description,
        keyPoints: points,
        materials,
        howToUse: b.howToUse ?? null,
        maker: b.maker,
        returnsText: b.returnsText ?? null,
        gstRate: "0",
        hsnCode: "4901",
        tracked: b.tracked ?? true,
        stock: variants.length ? 0 : (b.stock ?? 0),
        lowStockAlert: b.lowStockAlert ?? 2,
        images: [drawn(b.slug, `Cover of ${b.name} by ${b.author}`)],
        variants,
        demand: b.demand,
        seasonal: b.seasonal ?? null,
        reviews: b.reviews ?? [],
    };
}

