const NB_STOCK_OVERRIDE: Record<string, number> = {
    "A6 · Dotted · Kesari": 0,
    "A5 · Plain · Charcoal": 2,
    "A6 · Plain · Forest": 1,
};

const notebookVariants: DemoVariant[] = NB_SIZES.flatMap((size) =>
    NB_RULINGS.flatMap((ruling) =>
        NB_COVERS.map((cover, ci) => {
            const title = `${size} · ${ruling} · ${cover}`;
            const stock =
                NB_STOCK_OVERRIDE[title] ??
                (size === "A5" ? 12 : 8) +
                    (ruling === "Dotted" ? 4 : 0) -
                    ci * 2;
            const image = cover === "Forest" ? 0 : cover === "Indigo" ? 1 : 4;
            return v(
                title,
                `PGD-FNB-${size}-${ruling[0]}-${cover.slice(0, 3).toUpperCase()}`,
                size === "A5" ? "349" : "249",
                stock,
                image,
            );
        }),
    ),
);

