const INK_STOCK = [9, 14, 6, 8, 5, 0, 16, 7, 2, 10, 4, 18];

function item(
    p: Omit<
        DemoProduct,
        "price" | "mrp" | "status" | "returnsText" | "seasonal"
    > &
        Partial<
            Pick<
                DemoProduct,
                "price" | "mrp" | "status" | "returnsText" | "seasonal"
            >
        >,
): DemoProduct {
    return {
        ...p,
        price: p.price ?? cheapest(p.variants),
        mrp: p.mrp ?? null,
        status: p.status ?? "PUBLISHED",
        returnsText: p.returnsText ?? null,
        seasonal: p.seasonal ?? null,
    };
}

